// Fail-Fast Example: ArrayList
List<String> list = new ArrayList<>(List.of("A", "B"));
for (String s : list) {
    list.add("C"); // Throws ConcurrentModificationException
}

// Fail-Safe Example: CopyOnWriteArrayList
List<String> cowList = new CopyOnWriteArrayList<>(List.of("A", "B"));
for (String s : cowList) {
    cowList.add("C"); // Safe, iteration continues on the original snapshot
}
